    15	 * owner's id. Otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} absent.
    16	 *
    17	 * <p>Runs after {@link BuildOwner} (telephone, lastName and postcode are in their stored form) and
    18	 * after {@link CheckOwnerIdentityUnique} (so a hard duplicate has already been rejected), and before
    19	 * {@link SaveOwner} so the flag is compared only against existing owners. When several existing
    20	 * owners match, the one with the lowest id wins for a deterministic result.
    21	 */
    22	public class AssignPossibleDuplicate {
    23	
    24	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
    25	        String lastName = normalize(owner.getLastName());
    26	        String postcode = normalize(owner.getPostcode());
    27	        String telephone = normalize(owner.getTelephone());
    28	        owner.setPossibleDuplicate(false);
    29	        owner.setPossibleDuplicateOf(null);
    30	        if (postcode.isEmpty()) {
    31	            return; // no postcode to match on
    32	        }
    33	        Owner match = null;
    34	        for (Owner existing : ownerRepository.findAll()) {
    35	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
    36	                continue; // never a duplicate of itself
    37	            }
    38	            if (lastName.equals(normalize(existing.getLastName()))
    39	                    && postcode.equals(normalize(existing.getPostcode()))
    40	                    && !telephone.equals(normalize(existing.getTelephone()))) {
    41	                if (match == null || existing.getId() < match.getId()) {
    42	                    match = existing;
    43	                }
    44	            }
    45	        }
    46	        if (match != null) {
    47	            owner.setPossibleDuplicate(true);
    48	            owner.setPossibleDuplicateOf(match.getId());
    49	        }
    50	    }
    51	
    52	    private static String normalize(String value) {
    53	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
